INSERT INTO notes (id, subject_id, subject_name, dept_code, section, title, description, file_name, file_size, file_url, author_id, author_name, upload_date) VALUES
  ('note-01', 'sub-dsa', 'Data Structures & Algorithms', 'CSE', 'CSE-B', 'Unit 1: Arrays, Stacks and Queues', 'Comprehensive notes covering memory allocation, amortized complexity, and array applications.', 'Unit_1_Arrays_and_Stacks.pdf', '3.4 MB', '/uploads/sample_notes.pdf', 'usr-fac-01', 'Prof. R.K. Sharma', '2026-09-15'),
  ('note-02', 'sub-dsa', 'Data Structures & Algorithms', 'CSE', 'CSE-B', 'Unit 2: Non-Linear Data Structures (Trees & Graphs)', 'Binary trees, AVL balancing, Graph traversals (BFS, DFS), and shortest path algorithms.', 'Unit_2_Trees_and_Graphs.pdf', '4.8 MB', '/uploads/sample_notes.pdf', 'usr-fac-01', 'Prof. R.K. Sharma', '2026-09-28'),
  ('note-03', 'sub-dsa', 'Data Structures & Algorithms', 'CSE', 'CSE-B', 'Trees & Graphs: Important Exam Questions & Solutions', 'Curated university previous years questions with step-by-step tree dry runs.', 'Trees_Important_Questions.pdf', '2.1 MB', '/uploads/sample_notes.pdf', 'usr-fac-01', 'Prof. R.K. Sharma', '2026-10-02'),
  ('note-04', 'sub-dbms', 'Database Management Systems', 'CSE', 'CSE-B', 'Relational Algebra & SQL Normalization (1NF to BCNF)', 'Functional dependencies, lossless join decomposition, and 3NF/BCNF normalization rules.', 'DBMS_Normalization_Masterclass.pdf', '5.2 MB', '/uploads/sample_notes.pdf', 'usr-fac-02', 'Dr. Priya Verma', '2026-09-20'),
  ('note-05', 'sub-os', 'Operating Systems', 'CSE', 'CSE-B', 'Process Synchronization & Deadlock Handling', 'Semaphores, Peterson algorithm, Dining Philosophers, and Bankers Algorithm safety check.', 'OS_Synchronization_Deadlocks.pdf', '3.9 MB', '/uploads/sample_notes.pdf', 'usr-fac-03', 'Prof. Amit Sen', '2026-09-24'),
  ('note-06', 'sub-math', 'Discrete Mathematics', 'CSE', 'CSE-B', 'Graph Theory & Combinatorics Handouts', 'Eulerian and Hamiltonian graphs, planar graphs, coloring, and pigeonhole principle.', 'Discrete_Math_Graphs.pdf', '2.7 MB', '/uploads/sample_notes.pdf', 'usr-fac-04', 'Dr. Neha Gupta', '2026-09-18');
INSERT INTO assignments (id, subject_id, subject_name, dept_code, section, title, description, due_date, max_marks, author_id, author_name, file_url, status) VALUES
  ('asg-01', 'sub-dsa', 'Data Structures & Algorithms', 'CSE', 'CSE-B', 'Assignment 1: Balanced BST & AVL Rotations', 'Implement AVL Tree insertion with single and double rotations. Benchmark against plain BST.', '2026-10-15', 20, 'usr-fac-01', 'Prof. R.K. Sharma', '/uploads/sample_assignment.pdf', 'Active'),
  ('asg-02', 'sub-dbms', 'Database Management Systems', 'CSE', 'CSE-B', 'Assignment 2: Complex Queries & Transaction Isolation', 'Write complex SQL with window functions and analyze ACID consistency anomalies.', '2026-10-20', 25, 'usr-fac-02', 'Dr. Priya Verma', '/uploads/sample_assignment.pdf', 'Active'),
  ('asg-03', 'sub-os', 'Operating Systems', 'CSE', 'CSE-B', 'Assignment 1: CPU Scheduling Simulator', 'Simulate Round Robin and Priority scheduling algorithms and calculate average waiting time.', '2026-10-22', 20, 'usr-fac-03', 'Prof. Amit Sen', '/uploads/sample_assignment.pdf', 'Active');
