INSERT INTO doubts (id, student_id, student_name, student_roll, student_avatar, department, section, subject_id, subject_name, faculty_id, faculty_name, question, attachment_url, attachment_name, status) VALUES
  ('dbt-01', 'usr-stu-73', 'Rahul Sharma', 'CSE23B023', 'https://api.dicebear.com/7.x/avataaars/svg?seed=RahulSharma23', 'CSE', 'CSE-B', 'sub-dsa', 'Data Structures & Algorithms', 'usr-fac-01', 'Prof. R.K. Sharma', 'Sir, I don''t understand how the AVL tree double rotation (Left-Right) recalculates the new root and height in the code. Could you please clarify with an example?', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=600&q=80', 'avl_tree_doubt_diagram.jpg', 'Answered'),
  ('dbt-02', 'usr-stu-73', 'Rahul Sharma', 'CSE23B023', 'https://api.dicebear.com/7.x/avataaars/svg?seed=RahulSharma23', 'CSE', 'CSE-B', 'sub-dbms', 'Database Management Systems', 'usr-fac-02', 'Dr. Priya Verma', 'Ma''am, in BCNF decomposition, if a functional dependency X -> Y has X not as a superkey, do we always lose dependency preservation?', '', '', 'Waiting for Teacher'),
  ('dbt-03', 'usr-stu-73', 'Rahul Sharma', 'CSE23B023', 'https://api.dicebear.com/7.x/avataaars/svg?seed=RahulSharma23', 'CSE', 'CSE-B', 'sub-math', 'Discrete Mathematics', 'usr-fac-04', 'Dr. Neha Gupta', 'Ma''am, regarding Euler formula for planar graphs V - E + R = 2: how does this hold when the graph is disconnected into k components?', '', '', 'Answered'),
  ('dbt-04', 'usr-stu-52', 'Priya Verma', 'CSE23B002', 'https://api.dicebear.com/7.x/avataaars/svg?seed=PriyaVerma2', 'CSE', 'CSE-B', 'sub-dsa', 'Data Structures & Algorithms', 'usr-fac-01', 'Prof. R.K. Sharma', 'Sir, how to determine whether to use Dijkstra or Bellman-Ford when graphs have negative cycles?', '', '', 'Waiting for Teacher');
INSERT INTO doubt_replies (id, doubt_id, author_id, author_name, author_role, message) VALUES
  ('rep-01', 'dbt-01', 'usr-fac-01', 'Prof. R.K. Sharma', 'faculty', 'Hello Rahul. In an LR rotation, you first perform a left rotation on the left child of the unbalanced node, which transforms the zig-zag shape into a straight left-left line. Then you execute a standard right rotation on the unbalanced parent. Look at step 2 in the Unit 2 slides (page 34). I will also demonstrate this on the blackboard in Monday''s tutorial session.'),
  ('rep-02', 'dbt-03', 'usr-fac-04', 'Dr. Neha Gupta', 'faculty', 'Good observation, Rahul! For a planar graph with k connected components, the generalized formula is V - E + R = 1 + k. In a single connected component k=1, giving the familiar V - E + R = 2.');
INSERT INTO dpp_sets (id, subject_id, subject_name, title, questions_count, streak_day) VALUES
  ('dpp-dsa', 'sub-dsa', 'Data Structures', 'Today''s Practice: Trees & Heaps', 5, 14),
  ('dpp-dbms', 'sub-dbms', 'DBMS', 'Today''s Practice: Normalization & Transactions', 5, 9);
INSERT INTO dpp_questions (id, dpp_set_id, question, options, correct_index, explanation) VALUES
  ('q1', 'dpp-dsa', 'What is the worst-case time complexity of searching in an AVL tree with n nodes?', '["O(1)","O(log n)","O(n)","O(n log n)"]'::jsonb, 1, 'Because AVL trees maintain strict height balancing (|hL - hR| <= 1), the maximum height is 1.44 log n, giving O(log n) worst case.'),
  ('q2', 'dpp-dsa', 'In a min-heap, where is the second minimum element always located?', '["At the root","Either index 1 or 2 (children of root)","At any leaf node","At the last index"]'::jsonb, 1, 'In a min-heap, the smallest element is at the root. The second smallest must be one of the immediate children of the root.'),
  ('q3', 'dpp-dsa', 'Which tree traversal gives the keys of a Binary Search Tree in sorted ascending order?', '["Preorder","Inorder","Postorder","Level-order"]'::jsonb, 1, 'Inorder traversal visits Left Subtree -> Node -> Right Subtree, which yields strictly sorted keys for a BST.'),
  ('q4', 'dpp-dsa', 'What is the maximum number of nodes in a binary tree of height h (where root is height 0)?', '["2^(h+1) - 1","2^h","2^(h-1)","2^(h+1)"]'::jsonb, 0, 'A full binary tree has 1 + 2 + 4 + ... + 2^h = 2^(h+1) - 1 nodes.'),
  ('q5', 'dpp-dsa', 'Which balance factor triggers an LR (Left-Right) rotation in an AVL tree?', '["Node BF = +2, Left child BF = -1","Node BF = -2, Right child BF = +1","Node BF = +2, Left child BF = +1","Node BF = 0"]'::jsonb, 0, 'An LR rotation occurs when a node has balance factor +2 and its left child is right-heavy (balance factor -1).'),
  ('db-q1', 'dpp-dbms', 'Which normal form eliminates partial dependency on a candidate key?', '["1NF","2NF","3NF","BCNF"]'::jsonb, 1, 'Second Normal Form (2NF) enforces 1NF and guarantees that no non-prime attribute is functionally dependent on a proper subset of any candidate key.'),
  ('db-q2', 'dpp-dbms', 'In ACID properties, which property ensures that all transaction operations complete or none do?', '["Atomicity","Consistency","Isolation","Durability"]'::jsonb, 0, 'Atomicity follows the all-or-nothing rule.'),
  ('db-q3', 'dpp-dbms', 'What type of lock allows multiple concurrent transactions to read data simultaneously?', '["Exclusive Lock (X)","Shared Lock (S)","Intent Exclusive Lock","Update Lock"]'::jsonb, 1, 'A Shared lock permits concurrent reads while blocking write locks.'),
  ('db-q4', 'dpp-dbms', 'A relation R(A, B, C) with FD: A -> B and B -> C is in 2NF. Why is it NOT in 3NF?', '["Partial dependency exists","Transitive dependency exists (A -> C via B)","Multivalued dependency exists","No primary key exists"]'::jsonb, 1, 'Because B is not a superkey and C is not a prime attribute, the transitive dependency A -> B -> C violates 3NF.'),
  ('db-q5', 'dpp-dbms', 'Which isolation level prevents Dirty Reads, Non-repeatable Reads, and Phantom Reads?', '["Read Uncommitted","Read Committed","Repeatable Read","Serializable"]'::jsonb, 3, 'Serializable is the highest isolation level providing complete isolation against all concurrency anomalies.');
